insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('TR', 'TR-P-EX', 'Alış, istisna kapsamındaki mal veya hizmet', '{}'::jsonb, 'BSMV kapsamındaki bir sigorta ya da finansal işlem gibi, üzerinde hiç KDV hesaplanmamış bir alış.', 'percent', 0, 'purchase', 'exempt', date '1985-01-01', null, '3065 sayılı Kanun, madde 17/4-e — satıcı BSMV kapsamında işlem yaptığından faturada KDV hesaplanmaz, dolayısıyla indirilecek bir tutar da doğmaz.', 'E', null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null),
  ('TR', 'TR-P-IMP', 'Alış, mal ithalatı, gümrükte ödenen ve indirilebilir KDV', '{}'::jsonb, 'Yurt dışından satın alınan ve Türkiye gümrük bölgesine giren bir malın ithalinde gümrük idaresine, gümrük vergisi ile birlikte ve aynı anda ödenen KDV.', 'percent', 20, 'purchase', 'import', date '2023-07-10', null, '3065 sayılı Kanun, madde 1/2 (her türlü mal ithalatı verginin konusuna girer); madde 21 (ithalatta matrah, malın gümrük vergisi tarhına esas kıymeti — bulunmadığı hâllerde CİF değeri — artı ithalat sırasında ödenen her türlü vergi, resim, harç ve paylardır); madde 46/2 (ithalde alınan KDV, gümrük vergisi ile birlikte ve aynı zamanda ödenir); madde 29 (bu KDV, ödendiği dönemde indirim konusu yapılır). Türkiye Avrupa Birliği gümrük birliği dışında kaldığından mal ithalatında bir topluluk içi alım (intracom_acquisition_goods) değil, doğrudan bir ithalat söz konusudur ve bu KDV — Körfez ülkeleri paketlerinin (AE, SA) aksine — dönem beyannamesinde bir sorumluluk (reverse charge) olarak değil, gümrükte fiilen ödenmiş ve sonradan indirilen bir tutar olarak izlenir.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null),
  ('TR', 'TR-P-NR', 'Alış, KDV mükellefi olmayan satıcıdan', '{}'::jsonb, 'Esnaf muaflığından yararlanan ya da KDV mükellefiyeti bulunmayan bir satıcıdan yapılan, üzerinde KDV hesaplanmamış alış.', 'percent', 0, 'purchase', 'not_subject', date '1985-01-01', null, 'Satıcı 3065 sayılı Kanun''un mükellefi olmadığından (madde 1 ve madde 8) fatura üzerinde hesaplanmış bir KDV yoktur.', 'O', null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null),
  ('TR', 'TR-P-RC-SVC', 'Alış, yurt dışından hizmet ithali, sorumlu sıfatıyla KDV', '{}'::jsonb, 'Türkiye''de ikametgâhı, işyeri, kanuni merkezi ve iş merkezi bulunmayan bir satıcıdan alınan ve Türkiye''de faydalanılan bir hizmet — hizmeti alan, KDV''yi kendisi hesaplayıp sorumlu sıfatıyla beyan eder.', 'percent', 20, 'purchase', 'foreign_services_received', date '2023-07-10', null, '3065 sayılı Kanun, madde 1 (hizmetten Türkiye''de faydalanılması verginin konusuna sokar) ve madde 9/1 (Maliye Bakanlığı, Türkiye''de ikametgâhı, işyeri, kanuni ve iş merkezi bulunmayanlar tarafından yapılan işlemlerde, işleme taraf olanı verginin ödenmesinden sorumlu tutabilir; Katma Değer Vergisi Genel Uygulama Tebliği I/C-2.1.2.1 bu sorumluluğu tam tevkifat olarak düzenler). Bu KDV, 2 No''lu KDV Beyannamesi ile ayrı olarak beyan edilip ödenir — bu pack''in tax_report.json''ı yalnızca 1 No''lu KDV Beyannamesini modeller, bu yüzden bu tutarın kendisi hiçbir kutuya yazılmaz; madde 29 uyarınca aynı dönemde 1 No''lu beyannamede indirim konusu yapılabilen payı ise İndirilecek KDV tablosunda izlenir.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-genel-uygulama-tebligi', null, null, null, null),
  ('TR', 'TR-P-RR10', 'Alış, indirimli oran, KDV %10, indirilebilir', '{}'::jsonb, '(II) sayılı listede sayılan bir alış.', 'percent', 10, 'purchase', 'domestic', date '2023-07-10', null, '3065 sayılı Kanun, madde 28 ve madde 29; 2007/13033 sayılı Bakanlar Kurulu Kararı eki (II) sayılı liste.', 'S', null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-oran-karari', null, null, null, null),
  ('TR', 'TR-P-SR', 'Alış, genel oran, KDV %20, indirilebilir', '{}'::jsonb, 'Genel orana tabi ve indirim hakkı doğuran alış.', 'percent', 20, 'purchase', 'domestic', date '2023-07-10', null, '3065 sayılı Kanun, madde 28 (oran) ve madde 29 (mükellefler, faaliyetlerine ilişkin olarak kendilerine yapılan teslim ve hizmetler dolayısıyla hesaplanan KDV''yi, faaliyetlerine ait vergiye tabi işlemler üzerinden hesaplanan KDV''den indirebilirler).', 'S', null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null),
  ('TR', 'TR-S-EX-FIN', 'Satış, BSMV kapsamındaki işlemler istisnası', '{}'::jsonb, 'Banka ve Sigorta Muameleleri Vergisi kapsamına giren işlemler ile sigorta acente ve prodüktörlerinin sigorta muamelelerine ilişkin işlemleri.', 'percent', 0, 'sale', 'exempt', date '1985-01-01', null, '3065 sayılı Kanun, madde 17/4-e — Banka ve Sigorta Muameleleri Vergisi Kanunu kapsamına giren işlemler ile sigorta acente ve prodüktörlerinin sigorta muamelelerine ilişkin işlemleri vergiden müstesnadır. 6802 sayılı Gider Vergileri Kanunu madde 28 vd., sigorta şirketlerinin lehlerine aldıkları paraları BSMV''ye tabi tutar; madde 30 mükellefiyeti sigorta şirketlerine yükler, acente ve prodüktörlerin komisyonları da bu kapsamdadır. Türkiye Avrupa Birliği ortak KDV sistemi dışında olduğundan bu satırda bir VATEX kodu yerine yalnızca madde ataması yapılmıştır.', 'E', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null),
  ('TR', 'TR-S-OS', 'Satış, verginin konusuna girmeyen işlem', '{}'::jsonb, 'Türkiye''de yapılmayan, dolayısıyla 3065 sayılı Kanun''un konusuna hiç girmeyen teslim ve hizmetler.', 'percent', 0, 'sale', 'not_subject', date '1985-01-01', null, '3065 sayılı Kanun, madde 1 — Türkiye''de yapılan ticari, sınai, zirai faaliyet ve serbest meslek faaliyeti çerçevesindeki teslim ve hizmetler ile her türlü mal ve hizmet ithalatı verginin konusunu oluşturur; işlemin Türkiye dışında gerçekleşmesi hâlinde Kanunun konusuna girmez ve hiçbir kutuya yansımaz.', 'O', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null),
  ('TR', 'TR-S-RR1', 'Satış, indirimli oran, KDV %1', '{}'::jsonb, '2007/13033 sayılı Kararın eki (I) sayılı listede sayılan teslim ve hizmetler (temel gıda maddelerinin bir kısmı, gazete ve dergi, nakdi ve gayrinakdi kredi teminatı ücretleri gibi).', 'percent', 1, 'sale', 'domestic', date '2007-12-31', null, '3065 sayılı Kanun, madde 28; 2007/13033 sayılı Bakanlar Kurulu Kararı eki (I) sayılı liste — oran %1''dir ve 7346 sayılı Cumhurbaşkanı Kararı bu oranda değişiklik yapmamıştır. Bu pack (I) sayılı listenin tamamını madde madde taşımaz.', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-oran-karari', null, null, null, null),
  ('TR', 'TR-S-RR10', 'Satış, indirimli oran, KDV %10', '{}'::jsonb, '2007/13033 sayılı Kararın eki (II) sayılı listede sayılan teslim ve hizmetler (ör. gıda hizmeti/lokanta, konaklama, tekstil ürünlerinin bir kısmı, kitap ve süreli yayınlar).', 'percent', 10, 'sale', 'domestic', date '2023-07-10', null, '3065 sayılı Kanun, madde 28; 2007/13033 sayılı Bakanlar Kurulu Kararı eki (II) sayılı liste. 7346 sayılı Cumhurbaşkanı Kararı ile 10 Temmuz 2023''ten itibaren bu listedeki oran %8''den %10''a yükseltilmiştir. Bu pack (II) sayılı listenin tamamını madde madde taşımaz — hangi kalemlerin listede olduğu 2007/13033 sayılı Kararın ekinde okunmalıdır; bu, bir sonraki sürümde eklenecek bir eksikliktir.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-oran-karari', null, null, null, null),
  ('TR', 'TR-S-SR', 'Satış, genel oran, KDV %20', '{}'::jsonb, '(I) ve (II) sayılı listelerde sayılmayan her türlü teslim ve hizmet.', 'percent', 20, 'sale', 'domestic', date '2023-07-10', null, '3065 sayılı Kanun, madde 28 — katma değer vergisi oranı, vergiye tabi her bir işlem için %10''dur; Cumhurbaşkanı bu oranı dört katına kadar artırmaya, %1''e kadar indirmeye yetkilidir. Bu yetkiye dayanılarak yürürlükte olan 2007/13033 sayılı Bakanlar Kurulu Kararı, (I) ve (II) sayılı listelerde sayılmayan işlemler için oranı %18 olarak belirlemişti; 7346 sayılı Cumhurbaşkanı Kararı ile 10 Temmuz 2023''ten itibaren bu oran %20''ye yükseltilmiştir.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-oran-karari', null, null, null, null),
  ('TR', 'TR-S-ZR-EXP', 'Satış, ihracat istisnası (tam istisna)', '{}'::jsonb, 'İhracat teslimleri ve bu teslimlere ilişkin hizmetler.', 'percent', 0, 'sale', 'export', date '1985-01-01', null, '3065 sayılı Kanun, madde 11/1-a — ihracat teslimleri ve bu teslimlere ilişkin hizmetler vergiden müstesnadır; madde 12 bu istisnanın şartlarını (malın yurt dışındaki bir müşteriye veya yetkili gümrük antreposu işleticisine teslimi ve Türkiye Cumhuriyeti gümrük bölgesinden çıkışı) düzenler. Madde 32 uyarınca bu tam istisna kapsamındaki işlem nedeniyle yüklenilen ve indirim yoluyla giderilemeyen KDV, ihracatçıya iade olunur.', 'G', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'kdv-kanunu', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
