values
  ('TR', 'TR-KDV1', '1 No''lu Katma Değer Vergisi Beyannamesi', array['month']::declaration_period[], 'month'::declaration_period, date '2023-07-10', null, '3065 sayılı Kanun, madde 39 — katma değer vergisinde vergilendirme dönemi, faaliyette bulunulan takvim yılının birer aylık dönemleridir. Madde 42, beyannamenin şekil ve muhtevasının Hazine ve Maliye Bakanlığınca belirleneceğini söyler; bu belirleme Katma Değer Vergisi Genel Uygulama Tebliği ve GİB''in e-Beyanname sisteminin 1 No''lu KDV Beyannamesi ekranıdır. Bu pack, GİB''in canlı e-Beyanname ekranındaki kutu numaralarını (bu araştırma sırasında doğrulanabilir, tek başına erişilebilir bir metin olarak bulunamadı) değil, kanunun ve tebliğin sözünü ettiği içeriği — oran bazında matrah ve hesaplanan KDV, indirilecek KDV''nin kaynakları, ödenecek/devreden KDV — kendi kutu adlarıyla taşır. Bir GİB e-Beyanname ekranını bilen bir kişi bunu ilk kontrol etmelidir.', true,'day_of_month_after_period'::filing_deadline_rule, 28, null, '3065 sayılı Kanun, madde 41/1 — mükellefler KDV beyannamelerini vergilendirme dönemini takip eden ayın yirmidördüncü günü akşamına kadar vermekle yükümlüdür; madde 46/1 aynı günün akşamına kadar ödenmesini ister. 149 Sıra No''lu Vergi Usul Kanunu Sirküleri, 213 sayılı Kanunun mükerrer 28''inci maddesindeki yetkiye dayanarak, 1 Aralık 2022''den itibaren verilmesi gereken KDV beyannamelerinin verilme ve bu beyannameler üzerine tahakkuk eden verginin ödeme süresini, yeni bir belirleme yapılıncaya kadar, izleyen ayın 28''inci günü sonuna uzatmıştır — bu pack idari olarak fiilen uygulanan günü (28) taşır ve kanuni günü (24) burada kaydeder.', 'gib-beyan-uzatma', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
