update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}{YYYY}{NNNNNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = '213 sayılı Vergi Usul Kanunu, madde 230/1-2 — faturada düzenlenme tarihi ile fatura seri ve sıra numarasının bulunması zorunludur; madde 231/1 — faturalar sıra numarası dahilinde teselsül ettirilir. Elektronik fatura (e-Fatura) ve e-Arşiv Fatura uygulamasında bu numara, Gelir İdaresi Başkanlığı''nın teknik kılavuzlarının belirlediği üç karakterlik seri kodu, dört haneli yıl ve dokuz haneli müteselsil sayaçtan oluşan on altı karakterlik biçimde üretilir; format burada bir işletmenin seçebileceği bir örnektir, dayatılan tek biçim değildir.',
  numbering_source_key          = 'vuk',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = '3065 sayılı Kanun, madde 10 — vergiyi doğuran olay kural olarak (a) bendi uyarınca malın tesliminde veya hizmetin ifasında meydana gelir; (b) bendi bunu, teslim veya ifadan önce fatura ya da benzeri belge düzenlenmesi hâlinde, bu belgede gösterilen miktarla sınırlı olmak üzere belgenin düzenlenmesi anına ileri çeker — teslim/ifa kural, önceden kesilen fatura istisnadır, tıpkı Belçika''nın madde 16/22 - 17/22bis''i ve Lüksemburg''un madde 21 - 24, par. 1''i gibi. İthalatta vergiyi doğuran olay ayrıca (ı) bendinde düzenlenmiştir: gümrük vergisine tabi işlemlerde gümrük vergisi ödeme mükellefiyetinin başlaması, tabi olmayanlarda gümrük beyannamesinin tescili.',
  tax_point_source_key          = 'kdv-kanunu',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = '6102 sayılı Türk Ticaret Kanunu, madde 64/3 — tacirin tuttuğu ticari defterlere yapılan kayıtların, izleyen bir düzeltme kaydı düşülmeden değiştirilmesi, okunamaz hâle getirilmesi ya da kayıt sürecinin izlenmesini engelleyecek şekilde ortadan kaldırılması yasaktır; 213 sayılı Vergi Usul Kanunu, madde 231/1 faturaların sıra numarası dahilinde teselsül ettirilmesini ister. Bir işlenmiş faturanın taslağa dönmesi bu iki kuralı birlikte ihlal eder — numarası boşta kalır ve kaydı sanki hiç yapılmamış gibi geri almak, izleyen bir düzeltme kaydı düşmeden değişiklik yapmak demektir. Düzeltme, 3065 sayılı Kanun''un fatura ve benzeri belgeler için tanıdığı alacak dekontu (iade faturası) iledir.',
  posted_edit_policy_source_key = 'vuk',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'e-Fatura ve e-Arşiv Fatura, Gelir İdaresi Başkanlığı''nın (GİB) kendi platformu veya GİB onaylı özel entegratörler üzerinden, ciro eşiğini aşan mükellefler için 213 sayılı Vergi Usul Kanunu''nun mükerrer 257''nci maddesindeki yetkiye dayanan 509 Sıra No''lu Vergi Usul Kanunu Genel Tebliği (ve 535, 550, 573, 589 sıra no''lu değişiklik tebliğleri) ile zorunlu kılınmıştır — bu pack''in araştırmasının ulaştığı en güncel eşik, bir önceki yıl brüt satış hasılatı 3.000.000 TL ve üzerinde olan mükellefler için genel olarak, e-ticaret/gayrimenkul ve motorlu taşıt ticareti yapanlar için 500.000 TL olarak, izleyen yılın 1 Temmuz''undan itibaren geçerlidir; 1 Ocak 2026''dan itibaren bilanço esasına göre defter tutan hiçbir mükellef artık kâğıt fatura düzenleyemez, tutarı ne olursa olsun e-Fatura veya e-Arşiv Fatura düzenlemek zorundadır. `profile` bu yüzden boş bırakılmıştır: e-Fatura ve e-Arşiv Fatura, UBL-TR (UBL 2.1''in GİB tarafından yerelleştirilmiş bir alt kümesi) biçiminde yazılır ve GİB''in kendi platformu ya da bir özel entegratör üzerinden GİB''e iletilir — iki taraf arasında doğrudan bir EN 16931 profili (Peppol BIS, Factur-X, XRechnung, bir PINT) değişimi değil, idarenin kendisinin arada durduğu bir teyit (clearance benzeri) modelidir; packages/formats''ın hiçbir bileşeni bu XML''i yazmaz, imzalamaz ya da GİB''e iletmez. `party_scheme` ve `vat_scheme` de bu yüzden boştur: Türkiye''nin ISO 6523 kayıtlı bir katılımcı kimlik şeması yoktur (Peppol katılımcı kimlik şeması listesi v9.7''de TR yer almaz); bir e-Fatura mükellefi GİB tarafından atanan bir Posta Kutusu Etiketi (PK etiketi, ör. urn:mail:defaultpk@... biçiminde) ile adreslenir, VKN/TCKN ise ayrı bir alanda taşınır.',
  einvoice_source_key           = 'gib-efatura',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'TR';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('TR', 'reverse_charge', 'reverse_charge', 'KDV, alıcı tarafından sorumlu sıfatıyla 3065 sayılı Kanun''un 9''uncu maddesi uyarınca 2 No''lu KDV Beyannamesi ile beyan edilip ödenecektir.', '{}'::jsonb, 10, date '1970-01-01', null, '3065 sayılı Kanun, madde 9 — Maliye Bakanlığı (Hazine ve Maliye Bakanlığı), vergi alacağının emniyet altına alınması amacıyla, vergiye tabi işlemlere taraf olanları verginin ödenmesinden sorumlu tutabilir; Katma Değer Vergisi Genel Uygulama Tebliği I/C-2 bölümü bu sorumluluğun beyanının 2 No''lu KDV Beyannamesi ile yapılacağını düzenler. Faturaya basılacak cümlenin metni bu Kanunda yer almadığından pack''in kendi ifadesidir.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
